<template><AppLayout><div class="session-page"><div class="page-head"><div><el-button link @click="router.push('/app/employees')">← 返回</el-button><h2>{{session?.employeeName||'数字员工会话'}}</h2><p class="muted">本页面只展示本次进入后产生的消息</p></div><el-button @click="inspector=true" :disabled="!run">运行详情</el-button></div><div class="conversation"><el-empty v-if="!messages.length" description="输入第一条消息，开始工作"/><div v-for="item in messages" :key="item.key" :class="['message',item.role]"><div class="bubble">{{item.text}}</div></div><div v-if="active" class="progress">{{stateLabel(run?.state)}}</div></div><div class="composer"><el-input v-model="input" type="textarea" :rows="3" maxlength="4000" show-word-limit :disabled="active" placeholder="输入消息" @keydown.ctrl.enter="send"/><el-button type="primary" :loading="sending" :disabled="active||!input.trim()" @click="send">发送</el-button></div><el-drawer v-model="inspector" title="运行详情" size="420px"><el-descriptions v-if="run" :column="1" border><el-descriptions-item label="Run ID">{{run.runId}}</el-descriptions-item><el-descriptions-item label="Session ID">{{run.sessionId}}</el-descriptions-item><el-descriptions-item label="Definition Version">{{run.definitionVersionId}}</el-descriptions-item><el-descriptions-item label="State">{{run.state}}</el-descriptions-item></el-descriptions><el-timeline class="event-list"><el-timeline-item v-for="event in events" :key="event.sequenceNo" :timestamp="event.createdAt">#{{event.sequenceNo}} {{event.type}}<div>{{event.content}}</div></el-timeline-item></el-timeline></el-drawer></div></AppLayout></template>
<script setup lang="ts">import { computed,onBeforeUnmount,onMounted,ref } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import AppLayout from '../../layouts/AppLayout.vue'; import * as api from '../../api/app'; import type { Run,RunEvent,Session } from '../../api/app'; import { present,type ConversationItem } from '../../presenters/runEventPresenter'; const route=useRoute(); const router=useRouter(); const session=ref<Session>(); const run=ref<Run>(); const events=ref<RunEvent[]>([]); const messages=ref<ConversationItem[]>([]); const input=ref(''); const sending=ref(false); const inspector=ref(false); let timer:number|undefined; const active=computed(()=>!!run.value&&['QUEUED','RUNNING','WAITING_CONFIRMATION','CANCELLING'].includes(run.value.state)); async function load(){session.value=await api.getSession(String(route.params.sessionId))} async function send(){const value=input.value.trim();if(!value||active.value)return;sending.value=true;try{run.value=await api.createRun(String(route.params.sessionId),value);input.value='';events.value=[];messages.value=[];await poll()}finally{sending.value=false}} async function poll(){if(!run.value)return;const next=await api.getEvents(run.value.runId,events.value.at(-1)?.sequenceNo||0);if(next.length){events.value.push(...next);next.map(present).filter(Boolean).forEach(item=>messages.value.push(item as ConversationItem))}run.value=await api.getRun(run.value.runId);if(active.value)timer=window.setTimeout(poll,800)} function stateLabel(s?:string){return({QUEUED:'正在等待',RUNNING:'正在处理',WAITING_CONFIRMATION:'等待继续操作 / 补充信息',SUCCEEDED:'已完成',FAILED:'执行失败',CANCELLED:'已取消'}as Record<string,string>)[s||'']||s} onMounted(load); onBeforeUnmount(()=>{if(timer)clearTimeout(timer)});</script>
